# Usage: sample2.py <spec.json> <out.txt> — a numbered sample with no gaps, for a fluency judge
import json,sys
want='''0 9 * * *|*/15 9-17 * * 1-5|0 0 1 * *|30 * * * *|* 9-17 * * *|0 8,12,18 * * *|0 1/2 * * *|*/15 8,12,18 * * 1-5|* */2 * * *|5,20,45 9-17 * * 1-5|0 0,2,4,6,10,12,14,16,18,20,22 1 * *|*/10 0-2,4-23 * * *|0 9 * * 0-2,4-6|0 9 * * 1-6|0 0 1 * 5|0 0 1,15 1,7 1-5|0 0 1 6 5|0 9 1,3,5,7,9,11,13,17,19,21,23,25,27,29,31 * *|0 0 */5 * *|0 0 1 6-8 *|0 0 1 */2 *|0 9 * 1-11 *|0 0 LW * *|0 9 15W * *|0 0 L-1 * *|0 0 L-3 * *|0 0 * 6 1#2|30 1,13 * * *|0 */12 * * *|0 */6 * * *|0 */2 * * *|* 0 9 * * *|30 0 * * * *|* */15 9-17 * * 1-5|0,30 */15 9-17 * * 1-5|0 0 0 1 1 * 2030-2035|0 0 9 * * * 2028/4|0 0 9 * * * 2030/2|0-29 * * * *|5/10 * * * *|0 9 * 6 1|* * * * 0,6|0 22-2 * * *|30 */3 * * *|0 0 1W * *|0 9 * * 1,3,5|0 9 1-7 * *|0 9 * 6-8 *|0 * * * *|*/15 * * * *|* * 1 * *|0 9 * * 1|0 0 1 * 1-5|0 9 * 6 *|0 0 9 * * * 2030|0 0 1 1 *|15,45 */4 * * *|0 9-17 * * *|*/15 9 * * *|0 0 1,15 * *'''.split('|')
d=json.load(open(sys.argv[1])); seen={}
for sec in ('visible','held','hard'):
    for t,rows in d[sec]:
        for r in rows:
            if len(r)<3 or not r[2] or set(r[2])<= {'years','cron'}: seen.setdefault(r[0],r[1])
out=[seen[p] for p in want if p in seen]
out=list(dict.fromkeys(out))
open(sys.argv[2],'w').write('\n'.join(f"{i}. {s}" for i,s in enumerate(out,1))+'\n')
print(len(out))
